REVIEWED={}
DATE='2026-11-14'
def evidence(sid,where,result,claims=None):
    s=SOURCES[sid];s['verifiedAt']=DATE
    s['reviewEvidence']=[{'url':s['url'],'openedAt':DATE,'status':'read','sectionsOpened':[where],'result':result,'assertionsSupported':claims or [result]}]
    REVIEWED[sid]=True
def newsource(sid,title,author,organization,url,where,result,published='s.d.',access='full-text',limitation=''):
    SOURCES[sid]={'id':sid,'title':title,'author':author,'organization':organization,'published':published,'url':url,'verifiedAt':DATE,'passage':where,'access':access,'documentKind':'Publication originale scientifique ou institutionnelle','limitation':limitation}
    evidence(sid,where,result)
