MANIFEST=json.loads((ROOT/'health-media-manifest.json').read_text(encoding='utf-8'))
MEDIA={Path(m['src']).name:m for m in MANIFEST}
def photo(name,alt,caption):
    m=MEDIA[name]
    return {**{k:m[k] for k in ('src','author','sourceUrl','license','licenseUrl')},'kind':'photograph','alt':alt,'caption':caption}
def directphoto(name,alt,caption,sid,author='Zamir K. Punja et al.',prefix='/placard/school/health/'):
    return {'src':prefix+name,'kind':'photograph','alt':alt,'caption':caption,'author':author,'sourceUrl':SOURCES[sid]['url'],'license':'CC BY 4.0','licenseUrl':'https://creativecommons.org/licenses/by/4.0/'}
def diagram(title,nodes,sourceIds,kind='sequence',caption='Schéma de synthèse : les relations décrites ne constituent pas un diagnostic sur photographie.'):
    return {'kind':kind,'title':title,'nodes':[{'label':a,'detail':b} for a,b in nodes],'caption':caption,'sourceIds':sourceIds}
SPECS={}
def setarticle(index,questions,findings,paragraphs,*,image=None,diag=None,extra=(),blockers=(),lead=None):
    a=DATA['articles'][index];p=copy.deepcopy(a)
    if lead:p['lead']=lead
    for s in p['sections']:
        if s['id'] in paragraphs:s['paragraphs']=paragraphs[s['id']]
    p['sourceIds']=list(dict.fromkeys(p['sourceIds']+list(extra)))
    for s in p['sections']:s['sourceIds']=list(dict.fromkeys(s['sourceIds']+list(extra)))
    if image:p['image']=image
    if diag:p['diagram']=diag
    qids=[q['id'] for q in DATA['quiz'] if q['articleId']==a['id']]
    SPECS[index]={'id':a['id'],'questions':questions,'fullyRead':True,'findings':findings,'patch':p,'sourceIdsReviewed':[s for s in p['sourceIds'] if s in REVIEWED],'visual':{'status':'blocked' if blockers else 'verified','notes':('Page source et photographie locale examinées ; attribution/licence commerciale vérifiées. '+image['caption']) if image else 'Schéma original contrôlable : mécanisme ou niveau de preuve, sans prétendre photographier une maladie.'},'quizIdsReviewed':qids,'status':'blocked' if blockers else 'ready-for-integration','blockers':list(blockers)}
def notice(index,mechanism,identification,management=None,**kw):
    a=DATA['articles'][index]
    paras={s['id']:[' '.join(s['paragraphs'])] for s in a['sections']}
    paras['biology'].append(mechanism)
    paras['identification'].append(identification)
    if management:paras['management'].append(management)
    setarticle(index,[f"Quels organes et signes permettent d’orienter l’observation : {a['title'].lower()} ?",'Quel mécanisme explique les dégâts ou l’action biologique, et comment confirmer l’identité ?'],[f"Conservés après lecture : {a['lead']}",'Fragments réunis en paragraphes ; mécanisme et identification explicités ; portée géographique et limites du diagnostic conservées.'],paras,**kw)

setarticle(0,['Comment distinguer maladie infectieuse et trouble physiologique ?','Que montrent un oïdium, une pourriture et une atteinte racinaire ?'],['Conservés : Botrytis, oïdiums, Fusarium et oomycètes ; causes non infectieuses possibles.','Précisés : symptôme/signe, mécanismes et coexistence de causes ; noms Pythium/Globisporangium selon traitement taxonomique. Cornell inaccessible remplacé par CSU.'],{
'ref-maladies-chanvre-1':['Un symptôme est une réponse de la plante, comme le flétrissement ou la nécrose, c’est-à-dire la mort d’un tissu. Un signe est une manifestation de l’agent, comme un mycélium ou une sporulation. Un dépôt blanc poudreux de surface évoque un oïdium ; il ne permet pas à lui seul de choisir entre Golovinomyces ambrosiae et Podosphaera macularis, tous deux décrits sur chanvre dans une étude tchèque de 2024.','Botrytis cinerea est associé à la pourriture grise : les tissus brunissent et se dégradent, puis une sporulation grise peut apparaître. L’oïdium se développe surtout à la surface de tissus vivants, tandis qu’une pourriture implique une altération des tissus ; ces observations conduisent à des hypothèses différentes, à confirmer par examen.'],
'ref-maladies-chanvre-2':['Les racines et le collet peuvent être atteints par des Fusarium ou des oomycètes tels que Pythium. Leur altération réduit les fonctions d’absorption et peut entraîner un flétrissement de la partie aérienne, même si l’eau est présente dans le milieu. Le mycélium est un ensemble d’hyphes, des filaments dont l’aspect macroscopique n’est pas une identité d’espèce.','Les oomycètes constituent une lignée distincte des vrais champignons, malgré une croissance filamenteuse comparable. Plusieurs espèces anciennement placées dans Pythium sont aussi nommées Globisporangium ; EPPO conserve par exemple Pythium ultimum comme nom préféré et cite Globisporangium ultimum comme autre nom. Il faut rapprocher les synonymes avant de comparer les rapports.'],
'ref-maladies-chanvre-3':['Un manque d’oxygène autour des racines, un déséquilibre hydrique ou une nutrition perturbée peuvent aussi produire jaunissement et flétrissement. Ces troubles peuvent coexister avec une infection : la présence d’un microorganisme dans un prélèvement ne prouve donc pas qu’il explique toutes les lésions.','Le diagnostic confronte l’historique, les organes touchés, la répartition des plantes atteintes et l’évolution des symptômes. Un laboratoire peut examiner les tissus et rechercher un agent précis. Une identification et une preuve de causalité répondent à des questions différentes.']},image=directphoto('punja-2019-fig7.webp','Feuilles de Cannabis couvertes de plages blanches et vues microscopiques du champignon.','Oïdium sur Cannabis, Punja et al.2019, figure7 A–H. Identification publiée G. cichoracearum sensu lato ; cette planche ne prouve pas à elle seule G. ambrosiae ou P. macularis.','health-atlas-punja-2019'),diag=diagram('Du symptôme à l’hypothèse',[('Observer','Organes, signes visibles et évolution.'),('Comparer','Causes infectieuses et physiologiques peuvent se cumuler.'),('Confirmer','Examen et tests adaptés ; distinguer détection et causalité.')],['health-lesson-diagnosis','health-atlas-diagnostic']))
setarticle(1,['Quels arthropodes consomment le chanvre et lesquels consomment leurs proies ?','Pourquoi la présence d’un auxiliaire ne garantit-elle pas la régulation ?'],['Conservés : différence ravageur/prédateur/parasitoïde et protection intégrée.','Ajoutés : mécanismes alimentaires, stade de l’auxiliaire et nom Aculops cannibicola/cannabicola ; prescriptions américaines exclues.'],{
'ref-ravageurs-auxiliaires-1':['Les arthropodes possèdent des appendices articulés. Ils comprennent notamment les insectes et les acariens. Phorodon cannabis est un puceron qui prélève la sève ; Tetranychus urticae et Aculops cannibicola, aussi écrit A. cannabicola, sont des acariens qui se nourrissent des tissus végétaux. Les thrips laissent des cicatrices en endommageant des cellules, tandis que les chenilles, larves de papillons, consomment directement des tissus avec leurs mandibules.','Les organes touchés, la saison et les conditions sous abri ou au champ modifient les interactions. Une liste d’espèces publiée en Floride ou en Caroline du Nord ne décrit pas automatiquement les ravageurs dominants d’une parcelle française.'],
'ref-ravageurs-auxiliaires-2':['Des larves de chrysopes et des coccinelles prédatrices consomment des pucerons ; certains acariens Phytoseiidae consomment des tétranyques. Un prédateur peut attaquer plusieurs proies au cours de sa vie. Un parasitoïde accomplit son développement aux dépens d’un hôte et finit généralement par le tuer ; les pucerons momifiés sont un signe possible de cette activité.','Le terme auxiliaire désigne un rôle dans une interaction. Le stade observé, les proies disponibles et les conditions locales comptent : des œufs de chrysope indiquent une présence, pas encore une consommation par les larves. Une attaque de proies photographiée démontre cette interaction, pas une baisse suffisante des populations à l’échelle du champ.'],
'ref-ravageurs-auxiliaires-3':['La protection intégrée articule prévention, observation, identification et moyens adaptés à la cible. Elle prend en compte les auxiliaires et l’évolution du foyer ; un moyen physique ou biologique possède lui aussi une plage d’efficacité et des contraintes.','En France, une autorisation phytopharmaceutique se rapporte à des usages et conditions définis. Les mentions naturel, agriculture biologique ou biocontrôle ne valent pas, à elles seules, autorisation sur chanvre. Le catalogue E-Phy et le libellé de l’usage doivent être distingués des recommandations américaines citées pour la biologie.']},image=photo('coccinella-larva.jpg','Larve de coccinelle au contact de pucerons sur une tige.','Larve de Coccinella septempunctata se nourrissant de pucerons, Gilles San Martin. Le végétal photographié n’est pas identifié comme chanvre.'),diag=diagram('Trois relations alimentaires',[('Phytophage','Consomme des cellules, de la sève ou des organes de la plante.'),('Prédateur','Capture des proies ; efficacité selon proies et stade.'),('Parasitoïde','Se développe dans ou sur un hôte qu’il finit généralement par tuer.')],['health-atlas-beneficial-purdue','health-atlas-aphids'],kind='comparison'))
setarticle(2,['Quelle différence entre un virus et un viroïde ?','Que prouvent les détections et les essais HLVd sur chanvre ?'],['Conservés : nature non codante du viroïde et prudence devant les co-infections de Washington.','Référence Warren2019 inaccessible : aucune inoculation de 2019 présentée comme relue. Source primaire Atallah2024 accessible remplace l’assertion et documente aussi le chanvre asymptomatique.'],{
'ref-virus-viroides-1':['Les virus possèdent un génome et codent des composants de leur cycle infectieux ; leurs architectures diffèrent. Les viroïdes sont de petits ARN circulaires simple brin non codants et dépourvus de capside, l’enveloppe protéique de nombreux virus. Ils utilisent les fonctions de la cellule végétale pour leur réplication. Ce ne sont ni des champignons ni des insectes.'],
'ref-virus-viroides-2':['Le Hop latent viroid, HLVd, infecte Cannabis. Dans une étude expérimentale publiée dans Viruses en 2024, le viroïde a été détecté dans des tissus de chanvre après inoculation ; les plantes étaient asymptomatiques lors de certains prélèvements. Asymptomatique signifie sans symptôme apparent à cet instant, et non exempt d’infection.','Le même travail observe une transmission à la descendance dans les croisements de chanvre étudiés. Cela établit une possibilité biologique dans ce matériel, pas une probabilité universelle pour toute graine. D’autres travaux décrivent un dépérissement variable selon les plantes ; l’importance des effets ne se déduit pas d’un simple résultat positif.'],
'ref-virus-viroides-3':['Une publication de 2023 rapporte Beet curly top virus, Citrus yellow vein-associated virus et HLVd dans des plantes symptomatiques de chanvre de deux sites de l’État de Washington. Des plantes hébergeaient plusieurs agents. Comme l’échantillonnage visait des plantes malades, ses proportions de positifs ne représentent pas la prévalence de toutes les cultures.','Un test moléculaire recherche une séquence ; un essai contrôlé peut tester la contribution d’un agent aux symptômes. Dans cette enquête, le rôle propre de CYVaV n’est pas séparé de celui des co-infections. Des feuilles déformées ne permettent donc pas de nommer le virus ou le viroïde.']},extra=['health-new-hlvd-2024','health-new-hlvd-pnw'],diag=diagram('Des preuves de portée différente',[('Observation','Déformation ou dépérissement : une réponse de la plante, non spécifique.'),('Détection','Séquence recherchée présente dans le tissu analysé ; co-infection possible.'),('Essai contrôlé','Comparer plantes infectées et témoins pour tester un effet causal.')],['health-atlas-viruses-wa-2023','health-new-hlvd-2024'],kind='evidence',caption='Le viroïde n’est pas visible sur une photographie ordinaire de feuille ; aucune image n’est proposée comme diagnostic de HLVd.'))
notice(3,'Les pièces buccales prélèvent le contenu de cellules foliaires. Leur altération produit une multitude de petits points pâles qui peuvent confluer ; les fines toiles sont produites par les acariens et ne sont pas du mycélium.','La photo montre adultes, œufs et fils de soie sur un revers de feuille. Les taches sombres et la couleur sont variables ; le comptage des pattes doit porter sur le stade : larve à six pattes, nymphes et adultes à huit.',image=directphoto('tetranychus.jpeg','Acariens tachés, œufs ronds et fils de soie au revers d’une feuille.','Tetranychus urticae sur chanvre, photo Whitney Cranshaw/Colorado State University, Bugwood1325020 ; NC State, CC BY4.','health-atlas-tetranychus',author='Whitney Cranshaw, Colorado State University, Bugwood.org',prefix='/placard/reference/health/'))
notice(4,'Le corps effilé et les deux paires de pattes situées vers l’avant distinguent cet ériophyide des tétranyques à huit pattes aux stades postlarvaires. Il endommage des cellules végétales sans produire de toile ; les tissus peuvent se bronzer ou se déformer lorsque les populations augmentent.','EPPO privilégie Aculops cannibicola et recense aussi A. cannabicola. Les très petites formes mobiles pâles nécessitent une observation grossie ; une feuille recourbée ne suffit pas. Le cycle et l’hivernation restent incomplètement documentés selon NC State.',extra=['health-new-aculops-ncsu'],image=directphoto('aculops.jpeg','Nombreux organismes très petits, blanchâtres et allongés sur une feuille de chanvre.','Aculops sur chanvre, Whitney Cranshaw/Colorado State University, Bugwood5574608, page NC State ; grossissement nécessaire à l’identification.','health-new-aculops-ncsu',author='Whitney Cranshaw, Colorado State University, Bugwood.org',prefix='/placard/reference/health/'))
notice(5,'Polyphagotarsonemus latus est un acarien tarsonémide polyphage, différent de l’ériophyide allongé Aculops. Son alimentation sur les tissus jeunes s’accompagne de déformations, épaississement et bronzage ; le dommage peut rester visible après que les acariens ont disparu de la zone examinée.','Il faut examiner à fort grossissement les formes mobiles et les œufs, à surface caractéristique, sur les tissus jeunes. La photographie montre un spécimen microscopique attribué à cette espèce, et non une déformation de feuille permettant à elle seule un diagnostic.',image=photo('broad-mite-egg.jpg','Spécimen microscopique d’un acarien, corps et pattes visibles sur fond clair.','Polyphagotarsonemus latus, Chazz Hesselein/Alabama Cooperative Extension System, Bugwood5438919, CC BY3. Le fichier illustre une forme mobile, pas des œufs ; l’hôte n’est pas établi comme chanvre.'))

notice(6,'Les thrips percent et vident des cellules superficielles : les plages endommagées réfléchissent la lumière et prennent un aspect argenté. De petits points noirs de déjections peuvent accompagner les cicatrices, tandis que les jeunes tissus se déforment en grandissant.','La notice regroupe des espèces, notamment Thrips tabaci et Frankliniella occidentalis signalées sur chanvre au New Hampshire. Un corps étroit et des ailes frangées chez l’adulte orientent vers les thrips ; l’espèce exige un examen morphologique, et les ailes ne caractérisent pas les larves.',image=photo('thrips-occidentalis.jpg','Adulte de thrips, très allongé, avec ailes étroites sur une feuille.','Frankliniella occidentalis adulte, Frank Peairs/Colorado State University, Bugwood5364132, CC BY3. Hôte non établi comme chanvre ; cliché reçu déjà recadré par Commons.'))
notice(7,'Phorodon cannabis introduit ses pièces buccales dans les tissus pour prélever de la sève élaborée du phloème. Le miellat est un rejet sucré et collant de cette alimentation ; il peut servir de support à une fumagine, croissance superficielle secondaire, différente d’une lésion directement causée par un champignon pénétrant la feuille.','Les formes ailées permettent la dispersion, les aptères se multiplient dans les colonies ; la couleur varie avec la saison. Phorodon humuli lui ressemble : l’avant de la tête et d’autres caractères microscopiques sont nécessaires à la séparation, pas seulement l’hôte ou la teinte.',image=directphoto('cranshaw-2017-aphids.jpeg','Colonies de pucerons pâles sur une feuille de chanvre.','Phorodon cannabis sur chanvre, Whitney Cranshaw/Colorado State University, Bugwood5565654, photographie de septembre2017 ; NC State, CC BY4.','health-atlas-aphids',author='Whitney Cranshaw, Colorado State University, Bugwood.org'))
notice(8,'Myzus persicae, puceron vert du pêcher, est polyphage : son association avec le chanvre ne signifie pas qu’il lui est inféodé. Comme les autres pucerons, il prélève de la sève, peut former des colonies et produire du miellat ; les formes ailées participent aux déplacements entre plantes.','NC State le cite parmi les pucerons signalés sur chanvre. L’inventaire floridien le cite parmi les signalements d’autres régions, sans le compter parmi ses quatre pucerons identifiés localement. Une photographie d’adulte ailé aide à comprendre la forme, mais les caractères de la tête, des antennes et des cornicules sont nécessaires à une détermination.',image=photo('myzus-persicae.jpg','Puceron adulte ailé avec longues antennes et abdomen vert.','Myzus persicae, Scott Bauer/USDA, domaine public fédéral américain ; hôte de la photographie non établi comme chanvre.'))
notice(9,'Les aleurodes sont des insectes hémiptères suceurs de sève, malgré leur aspect de petites mouches blanches. Après un premier stade mobile, leurs stades immatures restent fixés sur la feuille, tandis que les adultes ailés se dispersent ; œufs et immatures peuvent donc être présents sans envol spectaculaire.','Le port des ailes et les caractères des stades immatures aident à distinguer les aleurodes, mais une photographie d’adulte ne remplace pas une détermination. Purdue cite l’aleurode des serres dans les milieux protégés ; son absence d’un échantillonnage de Floride ne démontre ni son absence sur tout chanvre ni son absence en France.',image=photo('trialeurodes.jpg','Petit aleurode adulte aux ailes blanches sur la face d’une feuille.','Trialeurodes vaporariorum, Sanja565658, CC BY-SA3. Cliché sur un autre végétal : ne documente pas des dégâts sur chanvre.'))
notice(10,'Le nom Bemisia tabaci recouvre un complexe d’espèces cryptiques : elles peuvent se ressembler fortement tout en différant par leur biologie. Les immatures et adultes prélèvent la sève, et les adultes assurent la dispersion ; leur présence seule ne démontre pas la transmission d’un agent viral particulier.','L’étude floridienne a identifié MEAM1 dans son matériel. Ce résultat ne permet pas de nommer MEAM1 à partir de n’importe quelle photographie de B. tabaci, ni d’attribuer une feuille enroulée à un virus transmis par cet aleurode. Une analyse appropriée est nécessaire pour les lignées cryptiques.',image=photo('bemisia.jpg','Deux aleurodes aux ailes blanches et au corps jaune sur un revers velu de feuille.','Bemisia tabaci, Stephen Ausmus/USDA, domaine public fédéral américain. Le cliché ne distingue pas une lignée cryptique et n’établit pas l’hôte chanvre.'))
notice(11,'La chenille est le stade larvaire d’un papillon de la famille des Noctuidae. Chez Helicoverpa zea, ce stade consomme les fleurs et les structures portant les graines avec ses mandibules ; l’adulte ailé ne produit pas ces morsures. Les blessures et débris de consommation peuvent aussi faciliter des pourritures secondaires, sans identifier leur agent.','Les chenilles varient en couleur et plusieurs espèces peuvent attaquer les mêmes organes. Il faut associer caractères morphologiques, organe atteint et contexte géographique ; une chenille sur maïs illustre le taxon, pas une attaque observée sur chanvre.',image=photo('helicoverpa.jpg','Chenille striée se nourrissant sur un épi de maïs.','Helicoverpa zea au stade larvaire sur maïs, cyanocorax, CC BY-SA2 ; document comparatif du ravageur, pas photographie d’un dégât sur chanvre.'))
notice(12,'Après les premiers stades exposés, la chenille peut pénétrer dans une tige et y creuser une galerie. La perte de tissu et la fragilisation mécanique expliquent qu’une tige se casse ou qu’une partie de plante flétrisse ; ces effets diffèrent de simples morsures superficielles sur une feuille.','La présence de déjections et d’une galerie oriente vers un insecte foreur mais ne suffit pas à nommer Ostrinia nubilalis : comparer la larve et la disposition des dégâts avec d’autres foreurs. Le document CSU décrit l’hivernation sous forme de larve mûre dans des résidus de tige.',image=photo('ostrinia.jpg','Papillon beige aux ailes déployées portant des lignes transversales, posé sur une ombellifère.','Ostrinia nubilalis adulte, B. Schoenmakers, Arnhem2014, CC0. L’adulte photographié sur une inflorescence d’une autre plante ne montre pas la galerie produite par la chenille.'),diag=diagram('De la ponte à la galerie',[('Œufs et jeunes larves','Stades encore présents à la surface des organes.'),('Entrée dans la tige','La chenille se nourrit à l’intérieur et laisse une galerie.'),('Tige fragilisée','Des dégâts internes peuvent précéder la casse visible.')],['health-atlas-ostrinia']))
notice(13,'Grapholita delineana est un petit papillon de la famille des Tortricidae. Sa chenille attaque des bourgeons, des tissus de tige et parfois des structures portant les graines. Une atteinte à la base d’un bourgeon peut interrompre localement sa continuité avec la tige et provoquer son flétrissement, même si le reste de la plante demeure vert.','La chenille jeune est claire avec tête sombre, puis peut devenir rougeâtre à orangée ; cette évolution ne constitue pas une clé unique. Le document CSU décrit des larves dans les tiges ou les replis végétaux en hiver. Une photo d’adulte illustre le taxon sans prouver l’identité d’une larve trouvée dans une galerie.',image=photo('grapholita.jpg','Petit papillon sombre posé, ailes repliées au-dessus du corps.','Grapholita delineana adulte, pintail, CC BY4 ; le végétal photographié n’est pas établi comme chanvre et aucun dégât larvaire n’est illustré.'),diag=diagram('Deux observations à relier',[('Adulte','Papillon ailé, à identifier sur ses caractères.'),('Larve et organe','Chenille dans un bourgeon ou une tige ; dégâts à documenter séparément.')],['health-atlas-grapholita'],kind='comparison'))
notice(14,'L’altise du chanvre Psylliodes attenuata est un coléoptère : l’adulte possède des ailes antérieures durcies, les élytres, et des pattes postérieures adaptées au saut. Ses mandibules découpent de petites perforations dans les cotylédons et les premières feuilles ; une petite plantule supporte moins de perte de surface qu’une plante déjà développée.','Le guide français cite aussi le nom Psylliodes apicalis. Des trous dans une feuille ne suffisent pas à attribuer l’espèce : rechercher l’adulte et comparer ses caractères. La photographie montre un spécimen de référence, sans représenter un prélèvement français.',image=photo('psylliodes.jpg','Vue dorsale d’un petit coléoptère sombre, avec antennes et pattes postérieures développées.','Psylliodes attenuata, photographie M. Gamman/Agriculture et Agroalimentaire Canada, figure1a de Biodiversity Data Journal12:e120340, CC BY4 ; spécimen canadien.'))
notice(15,'Les limaces sont des mollusques gastéropodes et non des insectes. Leur appareil buccal râpe et prélève les tissus tendres : au stade de levée, une consommation de cotylédon ou de jeune tige peut supprimer une plantule. L’humidité facilite leur activité, ce qui explique le contexte frais et humide décrit par le guide français.','Les pertes de plantules doivent être rapprochées de morsures et d’observations de limaces ; une trace luisante seule n’est pas une mesure de densité. Plusieurs espèces sont possibles, et une photographie de Deroceras reticulatum illustre une limace sans déterminer toutes celles d’une parcelle.',image=photo('deroceras.jpg','Limace claire et tachetée, allongée sur un sol minéral.','Deroceras reticulatum, Deadstar, CC0 ; photographie hors culture, donnée comme exemple de gastéropode et non comme identification d’un foyer de chanvre.'))
notice(16,'Les oiseaux granivores consomment directement les graines, notamment autour du semis ; des pertes peuvent apparaître avant que les plantules soient visibles. Il s’agit d’une consommation de matière végétale, différente d’une infection ou d’un défaut de germination. La disponibilité des graines et le stade de culture modifient le risque.','Pigeons et corvidés sont cités dans le guide français. Une levée irrégulière peut aussi résulter du sol, de la qualité des semences ou d’autres organismes ; il faut confronter observations d’oiseaux en alimentation, graines manquantes et autres indices, plutôt que conclure à partir d’un oiseau posé à proximité.',image=photo('columba.jpg','Pigeon ramier debout dans l’herbe, cou portant une marque blanche.','Columba palumbus, Don Loarie, CC BY4. Cette photographie identifie un oiseau possible, sans montrer de consommation sur chanvre.'))
notice(17,'L’oïdium forme un mycélium superficiel et produit des conidies donnant l’aspect poudreux blanc. Les structures de nutrition sont en relation avec les cellules de l’hôte vivant : une plage blanche est un signe de colonisation fongique, tandis que le jaunissement éventuel est une réponse du tissu.','L’étude tchèque distingue deux types de conidies et obtient en2023 une séquence ITS attribuée à Golovinomyces ambrosiae. Des publications plus anciennes utilisaient G. cichoracearum au sens large ; les séquences ITS ne séparaient pas toujours les noms G. ambrosiae et G. spadiceus. La photographie de2019 illustre donc un oïdium, pas une confirmation rétrospective d’espèce.',extra=['health-atlas-punja-2019'],image=directphoto('punja-2019-fig7.webp','Quatre vues de dépôts poudreux sur Cannabis et quatre vues microscopiques du champignon.','Punja et al.2019, figure7 A–H, oïdium publié sous G. cichoracearum sensu lato. La planche montre le syndrome et des structures ; G. ambrosiae n’y est pas séparé de tous les taxons proches.','health-atlas-punja-2019'))

notice(18,'Podosphaera macularis est un champignon biotrophe : il tire ses ressources d’une plante vivante et forme à sa surface des hyphes et des conidies. Son dépôt poudreux ressemble à celui d’autres oïdiums ; la similitude des symptômes n’implique ni une même espèce ni une même réponse de tous les hôtes.','Dans l’étude tchèque, les conidies attribuées à Podosphaera contiennent des corps de fibrosine, contrairement aux conidies de Golovinomyces observées dans les mêmes prélèvements. L’identification combine morphologie et séquences ; les mélanges de champignons expliquent en partie les séquences difficiles à interpréter.',diag=diagram('Séparer deux oïdiums au microscope',[('Podosphaera','Conidies avec corps de fibrosine dans les observations publiées.'),('Golovinomyces','Conidies sans corps de fibrosine ; autres caractères et séquences à comparer.'),('Prélèvement mixte','Deux types peuvent coexister sur une feuille : examiner plusieurs structures.')],['health-atlas-powdery-2024'],kind='comparison'),blockers=['Photographie de P. macularis sur chanvre ou microphotographie correctement déterminée indispensable : figures2–3 Wiley identifiées, mais licence commerciale non établie. Ne pas substituer le Golovinomyces de Punja2019 ni une ancienne photo sur Rubus aujourd’hui attribuable à un autre taxon.'])
notice(19,'Un nécrotrophe colonise et exploite des tissus qu’il détruit. Botrytis cinerea peut produire un mycélium et des conidies sur les tissus atteints ; la succession brunissement–dégradation–sporulation explique qu’une inflorescence soit altérée avant que la moisissure soit franchement grise à l’extérieur.','La planche documentaire associe tissus malades, culture et microscope : ces éléments ont été reliés par l’étude, pas par la couleur seule. Des chenilles peuvent laisser des lésions et favoriser une pourriture secondaire, mais une morsure et une identification de Botrytis sont deux observations distinctes.',image=directphoto('punja-2019-fig4.webp','Inflorescences brunies, colonie en culture, structures microscopiques et lésions foliaires de Cannabis.','Pourriture grise de Cannabis attribuée à Botrytis cinerea, Punja et al.2019, figure4 A–I ; photographies et micrographies CC BY4. Les panneaux de culture et microscope ne sont pas l’aspect à l’œil nu d’une feuille.','health-atlas-punja-2019'))
notice(20,'Un sclérote est une masse compacte de mycélium durci permettant au champignon de persister entre des périodes favorables à sa croissance. Les sclérotes de Sclerotinia sclerotiorum peuvent apparaître dans ou sur les tiges atteintes ; ce ne sont ni des graines de chanvre ni des œufs d’insectes.','Le rapprochement de lésions de tige, d’un mycélium blanc et de sclérotes oriente l’identification. Plusieurs champignons peuvent produire des structures de survie et plusieurs pourritures peuvent blanchir les tissus : documenter leur position et confirmer si nécessaire, plutôt que conclure au seul feutrage.',image=photo('sclerotia.jpg','Structures noires compactes visibles dans une tige coupée.','Sclérotes attribués à Sclerotinia sclerotiorum, Kmcleveland, CC BY3. Hôte non précisé comme chanvre ; la photo explique la structure de survie, pas un diagnostic de parcelle.'),diag=diagram('Une structure persiste entre les cultures',[('Tissu colonisé','Le mycélium se développe dans des conditions favorables.'),('Sclérote','Une masse compacte de mycélium constitue une structure de survie.'),('Nouvel inoculum','La persistance entre cultures explique l’intérêt de l’historique de la parcelle.')],['health-atlas-hemp-france']))
notice(21,'Le genre Fusarium regroupe des organismes différents : un isolement ne donne pas à tous les membres le même pouvoir pathogène. Dans l’étude canadienne, des isolats de F. oxysporum et F. solani ont reproduit des symptômes après inoculation de plants enracinés puis ont été réisolés ; cette succession soutient la causalité pour les isolats et conditions testés.','Des racines ou un collet altérés peuvent perturber l’alimentation hydrique de la plante et provoquer un flétrissement aérien. La couleur d’une colonie ne suffit pas à déterminer un complexe d’espèces ; il faut associer les tissus prélevés à la caractérisation de l’isolat, et distinguer les expériences sur racines de celles sur inflorescences.',image=directphoto('punja-2019-fig5.webp','Cultures de trois champignons et inflorescences de Cannabis inoculées en expérience.','Punja et al.2019, figure5 : A–B Botrytis cinerea, C–D Fusarium oxysporum, E–F Penicillium olsonii. Ce sont des essais sur inflorescences ; la preuve racinaire est décrite séparément dans le texte. CC BY4, aucune réserve de réutilisation tierce dans cette légende.','health-atlas-punja-2019'))
notice(22,'Une fonte peut se produire avant la levée, par altération de la graine ou de la très jeune plantule, ou après la levée, lorsqu’une lésion affaiblit sa base. Une infection plus tardive peut dégrader racines et collet ; la baisse des fonctions racinaires aide à expliquer flétrissement et retard sans fournir à elle seule une identité d’agent.','La classification dépend des traitements : EPPO privilégie Pythium ultimum et recense Globisporangium ultimum comme autre nom. L’étude2019 rapporte plusieurs Pythium et laisse alors la pathogénicité de P. catenulatum sur Cannabis à confirmer ; ce constat daté ne doit pas devenir une absence universelle de pathogénicité. La production de spores mobiles n’est pas identique pour toutes les espèces.',lead='Pythium spp. et Globisporangium spp. : des oomycètes, distincts des vrais champignons, associés à certaines fontes et pourritures racinaires ; les noms varient selon les classifications.',extra=['health-lesson-oomycetes'],diag=diagram('Deux temps d’une atteinte racinaire',[('Avant ou près de la levée','Fonte : une jeune plante peut disparaître ou s’effondrer.'),('Plante plus développée','Racines et collet altérés : croissance et alimentation hydrique perturbées.'),('Identification','Confronter tissus, conditions racinaires et analyses ; plusieurs causes possibles.')],['health-atlas-punja-2019','health-lesson-oomycetes']),blockers=['Photographie de racines ou de fonte sur chanvre à licence commerciale vérifiée manquante. Punja2019 figure2 A,D,E,G reproduits sous permission tierce : ne pas republier toute la planche comme CC BY4. NC State2019 photographie Cochran/Thiessen sans licence explicite ; image APS de fonte « copyright-free » repérée mais téléchargement bloqué par contrôle Cloudflare.'])
notice(23,'Le terme rhizoctone couvre plusieurs taxons et le complexe Rhizoctonia solani comprend des groupes biologiquement distincts. La croissance du mycélium au contact des racines ou du collet peut léser les tissus ; mycélium et structures de survie maintiennent un inoculum dans le milieu selon le taxon.','Une microphotographie d’hyphes montre un niveau d’observation différent d’une lésion sur plante. Les caractères de ramification orientent l’examen, mais la caractérisation du groupe et le lien avec les tissus atteints demandent davantage qu’un flétrissement ou un angle de branchement isolé.',image=photo('rhizoctonia.png','Hyphes ramifiés observés au microscope, avec barre d’échelle.','Hyphes de Rhizoctonia à160×, Ninjatacoshell, CC BY-SA3 ; échantillon provenant du maïs selon la page source. Microphotographie comparative, pas diagnostic sur chanvre.'))
notice(24,'L’enroulement, la chlorose et le retard de croissance sont des réponses végétales compatibles avec plusieurs agents ou stress. Dans l’enquête de Washington, des séquences et tests moléculaires identifient BCTV et plusieurs souches ; ces résultats sont plus discriminants qu’une silhouette de feuille recourbée.','Le corpus rassemble des plantes choisies parce qu’elles présentaient des symptômes, et des co-infections étaient présentes. Un résultat positif indique la détection du virus dans l’échantillon analysé ; il ne fournit ni la fréquence de toutes les parcelles ni la part causale de chaque agent chez une plante co-infectée.',diag=diagram('Identifier BCTV, puis interpréter',[('Feuille enroulée','Symptôme non exclusif ; recueillir le contexte.'),('PCR et séquence','Identifier le virus et, dans l’étude, des souches.'),('Épidémiologie','Échantillonnage et vecteurs à étudier avant une estimation locale.')],['health-atlas-viruses-wa-2023'],kind='evidence',caption='Schéma de lecture de l’enquête, pas image d’un symptôme spécifique à BCTV.'))
notice(25,'Le nom Citrus yellow vein-associated virus décrit l’histoire de sa dénomination, pas une restriction absolue aux agrumes. Dans la note de Washington, la recherche moléculaire a retrouvé CYVaV dans du chanvre ; les infections multiples empêchent de lui attribuer séparément tous les symptômes observés.','La détection d’un ARN viral et la reproduction expérimentale d’une maladie répondent à deux questions différentes. Cette note établit la présence de CYVaV dans les échantillons, mais pas un symptôme exclusif du chanvre ni un cycle de transmission complet sur cette culture.',diag=diagram('Ce que la note établit',[('Présence','Séquences et RT-PCR sur des tissus de chanvre.'),('Co-infections','Plusieurs agents dans les mêmes plantes ou le même corpus.'),('Question ouverte','Contribution propre de CYVaV aux symptômes et voies dominantes sur chanvre.')],['health-atlas-viruses-wa-2023'],kind='evidence',caption='Aucune photographie n’est présentée comme diagnostic d’une maladie spécifique à CYVaV sur chanvre.'))
notice(26,'Le HLVd est un petit ARN circulaire non codant, sans capside. L’étude expérimentale de2024 suit son infection et sa détection dans plusieurs tissus de chanvre ; à certains prélèvements, les plantes infectées ne montrent pas de symptôme visible. Un agent peut donc se multiplier sans produire immédiatement une déformation reconnaissable.','Les formes HLVd et HpLVd désignent le même viroïde. La recherche par RT-PCR ou RT-qPCR doit être interprétée avec la qualité de l’échantillon et les contrôles du laboratoire. Des transmissions à la descendance ont été observées dans les croisements de chanvre étudiés en2024 ; aucun taux de transmission de ces essais n’est transposé à toute semence.',extra=['health-new-hlvd-2024','health-new-hlvd-pnw'],diag=diagram('Infection et symptôme ne sont pas équivalents',[('Matériel infecté','Le viroïde peut être présent dans plusieurs tissus.'),('Expression variable','Une plante peut être positive sans symptôme apparent.'),('Diagnostic','Test moléculaire et contexte, puis évaluation du lot.')],['health-new-hlvd-2024','health-new-hlvd-pnw'],kind='evidence',caption='Les photographies de dépérissement d’Arabidopsis dans l’étude2024 ne sont pas utilisées comme symptômes sur chanvre.'))
SPECS[26]['patch']['sections'][0]['paragraphs']=['Des publications nord-américaines rapportent HLVd sur Cannabis. L’étude expérimentale de2024 apporte des données d’infection, de déplacement dans la plante et de transmission à la descendance pour le matériel étudié ; elle ne mesure pas une prévalence française.','Les manifestations rapportées varient selon les plantes et le contexte. Une série d’échantillons adressés à un laboratoire n’est pas un échantillonnage représentatif de toutes les cultures.']
SPECS[26]['findings'].append('Retiré le récit d’inoculation californienne2019 non relu ; remplacé par les résultats effectivement lus de2024. Données canadiennes2023 non réutilisées comme preuve autonome.')
notice(27,'Chez les coccinelles prédatrices visées ici, larves et adultes peuvent consommer des pucerons. La larve allongée n’a pas encore la silhouette bombée de l’adulte : la métamorphose explique que deux organismes très différents d’aspect appartiennent au même cycle. La famille des Coccinellidae comprend aussi d’autres régimes alimentaires.','L’observation de pucerons capturés établit une interaction de prédation. Pour juger une régulation, il faut cependant suivre l’évolution des proies et de leurs dégâts : une larve en alimentation sur une tige ne mesure pas à elle seule l’efficacité dans toute une culture.',image=photo('coccinella-larva.jpg','Larve de coccinelle allongée et hérissée, se nourrissant parmi des pucerons.','Larve de Coccinella septempunctata mangeant des pucerons, Gilles San Martin, CC BY-SA2. Le cliché documente la relation alimentaire, sans établir l’hôte chanvre.'))
notice(28,'La larve de chrysope saisit de petites proies avec ses mandibules courbes ; les pucerons font partie de ses proies. Les œufs sont souvent portés par un pédoncule fin, puis la larve prédatrice passe par un cocon avant le stade adulte ailé. L’œuf n’est donc pas lui-même un stade qui chasse les pucerons.','Le document Colorado mentionne Chrysopa oculata, dont l’adulte est aussi prédateur. Cela ne se généralise pas aux adultes de toutes les chrysopes. La photographie montre une larve attribuée au complexe Chrysoperla carnea sensu lato : ce n’est pas une photographie de C. oculata et elle ne résout pas les espèces du complexe.',image=photo('chrysoperla.jpg','Larve de chrysope au corps allongé et aux mandibules courbes, sur une feuille.','Chrysoperla carnea sensu lato, larve photographiée à Arnhem en2017 par B. Schoenmakers/Waarneming.nl, CC BY3 ; hôte non établi comme chanvre.'),extra=['health-atlas-beneficial-purdue'])
notice(29,'La larve du parasitoïde se développe dans le puceron aux dépens de son hôte. Le puceron finit généralement par mourir et son enveloppe peut former une momie ; l’adulte parasitoïde en sort par un orifice d’émergence. Cet adulte est distinct du puceron brun visible sur la plante.','Une momie n’est ni une exuvie abandonnée lors d’une mue du puceron ni une identification certaine d’espèce de guêpe. Le signe renseigne sur une activité passée ; il faut examiner les hôtes, les adultes et l’évolution des colonies pour apprécier le résultat de la régulation.',image=photo('aphid-mummy.jpg','Puceron gonflé et brun, près d’exuvies sur un organe végétal.','Momie de puceron associée à un parasitoïde braconide, James Marchment/Insects Unlocked, University of Texas at Austin, CC0 ; hôte végétal non établi comme chanvre.'))
SPECS[29]['patch']['image']['author']='James Marchment / Insects Unlocked, University of Texas at Austin'
notice(30,'Les Phytoseiidae comprennent des acariens prédateurs dont les préférences alimentaires diffèrent. Phytoseiulus persimilis est spécialisé sur les tétranyques tisserands de la sous-famille Tetranychinae ; Neoseiulus californicus ou Amblyseius andersoni ont un régime plus large. Une preuve sur Tetranychus ne suffit donc pas pour conclure à la même efficacité sur Aculops.','Un petit acarien rapide n’est pas automatiquement un auxiliaire identifié. La photographie relie un prédateur et une proie déterminés, dans un milieu artificiel sur feuille de mandarinier ; elle illustre l’interaction et ne mesure pas une efficacité sur chanvre.',image=photo('phytoseiulus.png','Acariens rouge orangé, dont un prédateur au contact d’une proie, sur une feuille.','Phytoseiulus persimilis chassant Tetranychus urticae sur feuille de mandarinier en environnement artificiel, Noctum, CC BY-SA4 ; document comparatif, pas essai d’efficacité sur chanvre.'),diag=diagram('La proie compte autant que le prédateur',[('P. persimilis','Spécialisé sur les tétranyques tisserands.'),('Autres Phytoseiidae','Régimes plus larges selon l’espèce.'),('Sur chanvre','Identifier la proie ; données contre Aculops encore limitées dans le guide.')],['health-atlas-purdue-greenhouse'],kind='comparison'))

def write_batches():
    ranges=[range(0,6),range(6,12),range(12,18),range(18,24),range(24,31)]
    for number,indices in enumerate(ranges,1):
        if not all(i in SPECS for i in indices):continue
        articles=[SPECS[i] for i in indices]
        aids={a['id'] for a in articles}
        terms=[]
        for t in DATA['terms']:
            if t['articleId'] not in aids:continue
            definition=TERM_DEFINITIONS.get(t['id'],t['definition'])
            sid=[s for s in t['sourceIds'] if s in REVIEWED]
            if t['id'] in ('health-term-asymptomatic','health-term-viroid'):sid=list(dict.fromkeys(sid+['health-new-hlvd-2024','health-atlas-viroids-ictv']))
            terms.append({'id':t['id'],'definition':definition,'sourceIds':sid,'findings':['Définition relue individuellement ; distinction entre description et diagnostic conservée.']})
        ids=set(s for a in articles for s in a['patch']['sourceIds'])|set(s for t in terms for s in t['sourceIds'])
        out={'domain':'health','reviewedAt':DATE,'sources':[SOURCES[s] for s in SOURCES if s in ids],'articles':articles,'termReviews':terms,'quizPatches':[],'sensitivePoints':[{'sourceId':s,'note':FAILED[s]} for s in ids if s in FAILED]}
        (ROOT/f'batches/health-{number:02}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        print(f'health-{number:02}: {len(articles)} articles, {len(terms)} termes, {sum(len(a["quizIdsReviewed"]) for a in articles)} quiz, {sum(a["status"]=="blocked" for a in articles)} bloqués')
TERM_DEFINITIONS={
'health-term-mite':'Arthropode arachnide : les acariens comprennent des espèces phytophages et prédatrices. Le nombre de pattes dépend du groupe et du stade ; les ériophyides ont deux paires aux stades mobiles.',
'health-term-arthropod':'Animal à squelette externe et appendices articulés ; les insectes et les acariens en sont deux groupes distincts, comprenant des rôles alimentaires variés.',
'health-term-asymptomatic':'Sans symptôme apparent au moment de l’observation ; une plante asymptomatique peut néanmoins être infectée et donner un test moléculaire positif.',
'health-term-auxiliary':'Organisme qui contribue à limiter un organisme dommageable dans une interaction donnée, par exemple un prédateur de pucerons ; sa présence ne garantit pas une régulation suffisante.',
'health-term-fungus':'Organisme de la lignée des Fungi. Les champignons ont des rôles divers, pas tous pathogènes ; les oomycètes constituent une autre lignée malgré leur croissance souvent filamenteuse.',
'health-term-mycelium':'Ensemble d’hyphes, filaments constituant la croissance de nombreux champignons et oomycètes ; son aspect visible ne suffit pas à identifier une espèce.',
'health-term-necrosis':'Mort de cellules ou d’une portion de tissu végétal, observée par exemple comme une lésion brune ; elle peut avoir une cause infectieuse ou non infectieuse.',
'health-term-oomycete':'Organisme de la lignée des Straménopiles, distincte des vrais champignons malgré des ressemblances de croissance ; plusieurs Pythium causent des fontes ou pourritures racinaires.',
'health-term-parasitoid':'Organisme dont le développement se déroule dans ou sur un hôte, qu’il finit généralement par tuer ; à distinguer d’un prédateur qui peut capturer plusieurs proies.',
'health-term-viroid':'Petit ARN circulaire simple brin non codant, sans capside, qui utilise des fonctions de son hôte végétal pour se répliquer ; le HLVd en est un exemple.',
'health-term-virus':'Agent infectieux possédant un génome et dépendant de cellules hôtes pour sa multiplication. Les virus diffèrent par leur architecture et leur cycle ; un symptôme foliaire ne suffit pas à les identifier.'}
if __name__=='__main__':write_batches()
